// Font files imported by URL: Remotion's bundler (webpack asset/resource) turns each into a
// served file and the import into its URL. One pattern per pinned font package this film uses
// (the kit's own assets.d.ts declares the packages it loads itself).
declare module '@fontsource-variable/ibm-plex-sans/files/*.woff2' {
  const url: string;
  export default url;
}
declare module '@fontsource-variable/noto-sans-sc/files/*.woff2' {
  const url: string;
  export default url;
}
declare module '@fontsource-variable/jetbrains-mono/files/*.woff2' {
  const url: string;
  export default url;
}
